insert into echa_p_block (block_id, table_id, page, column_type, p_code, raw_text) values
(1,1,92,'prevention','P201','Obtain special instructions before use.  Highly recommended'),
(2,1,92,'prevention','P250','Do not subject to grinding/shock/friction/… .  if the explosive is mechanically sensitive …Manufacturer/supplier to specify applicable rough handling. Highly recommended if the  explosive is mechanically sensitive  Optional if the explosive is not mechanically sensitive'),
(3,1,92,'response','P370+P372+P380+P373','In case of fire: Explosion risk. Evacuate area. DO NOT fight fire when fire reaches explosives.  Highly recommended'),
(4,1,92,'storage','P401','Store in accordance with… … Manufacturer/supplier to specify local/regional/national/international regulations as applicable.  Highly recommended for inclusion in the safety data sheet. Specify the applicable regulation.'),
(5,1,92,'disposal','P501','Dispose of contents/container to … … in accordance with local/ regional/national/international regulations (to be specified). Manufacturer/supplier to specify whether disposal requirements apply to contents, container or both.  Recommended for inclusion in the safety data sheet if there are specific disposal requirements above the normal expectation for the disposal of chemicals.'),
(6,1,93,'prevention','P280','Wear protective gloves/protective clothing/eye protection/face protection. Manufacturer/supplier to specify the appropriate type of equipment.  Highly recommended to apply the full wording of P280'),
(7,2,94,'prevention','P210','Keep away from heat, hot surfaces, sparks, open flames and other ignition sources. No smoking.  Highly recommended'),
(8,2,94,'prevention','P230','Keep wetted with … - for substances and mixtures which are wetted, diluted, dissolved or suspended with a phlegmatiser in order to reduce or suppress their explosive properties (desensitized explosives) … Manufacturer/supplier to specify appropriate material.  Highly recommended'),
(9,2,94,'prevention','P234','Keep only in original packaging  Highly recommended'),
(10,2,94,'response','P370+P372+P380+P373','In case of fire: Explosion risk. Evacuate area. DO NOT fight fire when fire reaches explosives.  Highly recommended'),
