-- Исправлено две вещи: (1) порядок слов в строке - маркер списка уезжал в конец,
-- (2) резка по маркеру пункта вместо резки по слову, иначе 'It is recommended to
-- specify...' считалось отдельной рекомендацией. Уровней пять: добавлен Mandatory.
-- Класс и категория - замером по H-коду и сигнальному слову. Неразобранных: 0.

create table if not exists echa_p_block_note (
  block_id int not null references echa_p_block(block_id) on delete cascade,
  seq int not null, text text not null, primary key (block_id, seq));
alter table echa_p_block_note enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where tablename='echa_p_block_note') then
    create policy echa_p_block_note_read on public.echa_p_block_note for select to anon, authenticated using (true);
  end if;
end $$;

begin;
delete from echa_p_block_note; delete from echa_p_recommendation; delete from echa_p_block;
delete from echa_p_table_scope; delete from echa_p_table;






commit;
